import { useEffect, useMemo, useRef, useState } from 'react'
import { Box, ButtonBase, CircularProgress, InputBase } from '@mui/material'
import { getLanguage, t } from '../i18n'

// [emoji, group, words searched] (src/data, generated by npm run emojis)
type Emoji = [string, number, string]

// tabs: recent ones, then the groups of emojibase (2 = skin tones, left out)
const GROUPS: {group: number, icon: string, label: string}[] = [
	{group: -1, icon: '🕘', label: 'Recent'},
	{group: 0, icon: '😀', label: 'Smileys & emotions'},
	{group: 1, icon: '👋', label: 'People & body'},
	{group: 3, icon: '🐶', label: 'Animals & nature'},
	{group: 4, icon: '🍕', label: 'Food & drink'},
	{group: 5, icon: '✈️', label: 'Travel & places'},
	{group: 6, icon: '⚽', label: 'Activities'},
	{group: 7, icon: '💡', label: 'Objects'},
	{group: 8, icon: '❤️', label: 'Symbols'},
	{group: 9, icon: '🏁', label: 'Flags'},
]

const RECENT_KEY = 'unee.emojis.recent'
const RECENT_MAX = 24
// recent ones by default, before the first use
const DEFAULT_RECENT = ['👍', '😂', '🙏', '😄', '❤️', '🎉', '😉', '👌', '🔥', '😅', '🤔', '👏', '🙌', '😍', '✅', '💪']

// list of the language loaded once, in its own chunk
let cache: {lang: string, list: Emoji[]} | null = null
const load = async (lang: string):Promise<Emoji[]> => {

	if(cache?.lang === lang)return cache.list
	const data = (lang === 'fr') ? await import('../data/emojis-fr.json') : await import('../data/emojis-en.json')
	cache = {lang, list: data.default as Emoji[]}
	return cache.list

}

const readRecent = ():string[] => {

	try
	{

		const list = JSON.parse(localStorage.getItem(RECENT_KEY) ?? 'null')
		return Array.isArray(list) ? list.filter((e) => typeof e === 'string').slice(0, RECENT_MAX) : DEFAULT_RECENT

	}
	catch
	{

		return DEFAULT_RECENT

	}

}

const writeRecent = (list: string[]) => {

	try
	{

		localStorage.setItem(RECENT_KEY, JSON.stringify(list))

	}
	catch
	{

		// storage refused (private mode): recent ones kept for this page only

	}

}

const fold = (text: string) => text.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()

/**
 * emoji picker (messaging style): search in the language of the user, tabs by group, recent ones remembered in the browser
 */
export default function EmojiPicker({onPick, onClose}: {onPick: (emoji: string) => void, onClose: () => void})
{

	const lang = getLanguage().startsWith('fr') ? 'fr' : 'en'
	const [list, setList] = useState<Emoji[] | null>(cache?.lang === lang ? cache.list : null)
	const [query, setQuery] = useState('')
	const [recent, setRecent] = useState<string[]>(readRecent)
	const [group, setGroup] = useState(-1)
	const search = useRef<HTMLInputElement | null>(null)

	useEffect(() => {

		let cancelled = false
		load(lang).then((l) => { if(!cancelled)setList(l) })
		search.current?.focus()
		return () => { cancelled = true }

	}, [lang])

	const shown = useMemo(() => {

		if(!list)return []
		const q = fold(query.trim())
		if(q !== '')return list.filter((e) => fold(e[2]).includes(q)).slice(0, 200).map((e) => e[0])
		if(group === -1)return recent
		return list.filter((e) => e[1] === group).map((e) => e[0])

	}, [list, query, group, recent])

	const pick = (emoji: string) => {

		const next = [emoji, ...recent.filter((e) => e !== emoji)].slice(0, RECENT_MAX)
		setRecent(next)
		writeRecent(next)
		onPick(emoji)

	}

	const title = query.trim() !== '' ? t('Results') : t(GROUPS.find((g) => g.group === group)?.label ?? '')

	return (
		<Box role="dialog" aria-label={t('Emojis')} onKeyDown={(e) => { if(e.key === 'Escape'){ e.stopPropagation(); onClose() } }}
			sx={{display: 'flex', flexDirection: 'column', height: 340, bgcolor: 'var(--u-paper)', borderRadius: '12px', boxShadow: '0 10px 34px var(--u-shadow), 0 0 0 1px var(--u-border)', overflow: 'hidden'}}>
			<Box sx={{p: 1.25, pb: 0.75}}>
				<InputBase inputRef={search} fullWidth value={query} placeholder={t('Search an emoji')} onChange={(e) => setQuery(e.target.value)} inputProps={{'aria-label': t('Search an emoji')}}
					sx={{height: 34, px: 1.75, borderRadius: '17px', bgcolor: 'var(--u-chat-bar)', fontSize: 13.5}} />
			</Box>
			<Box role="tablist" sx={{display: 'flex', justifyContent: 'space-between', px: 0.75, borderBottom: '1px solid var(--u-border)', opacity: query.trim() !== '' ? 0.5 : 1}}>
				{GROUPS.map((g) => (
					<ButtonBase key={g.group} role="tab" aria-selected={group === g.group} aria-label={t(g.label)} title={t(g.label)} onClick={() => { setQuery(''); setGroup(g.group) }}
						sx={{width: 34, height: 34, fontSize: 18, borderBottom: '2px solid', borderColor: group === g.group ? 'primary.main' : 'transparent', opacity: group === g.group ? 1 : 0.55}}>{g.icon}</ButtonBase>
				))}
			</Box>
			<Box sx={{flex: '1 1 auto', minHeight: 0, overflowY: 'auto', px: 1.25, py: 1}}>
				<Box sx={{fontSize: 12, fontWeight: 600, color: 'var(--u-text3)', mb: 0.5}}>{title}</Box>
				{!list && <Box sx={{display: 'flex', justifyContent: 'center', py: 3}}><CircularProgress size={20} /></Box>}
				{list && shown.length === 0 && <Box sx={{fontSize: 13, color: 'var(--u-text3)', py: 1}}>{t('No emoji found')}</Box>}
				<Box sx={{display: 'grid', gridTemplateColumns: 'repeat(8, minmax(0, 1fr))', gap: '2px'}}>
					{shown.map((emoji) => (
						<ButtonBase key={emoji} aria-label={emoji} onClick={() => pick(emoji)} sx={{height: 38, borderRadius: '8px', fontSize: 24, lineHeight: 1, '&:hover': {bgcolor: 'var(--u-hover)'}}}>{emoji}</ButtonBase>
					))}
				</Box>
			</Box>
		</Box>
	)

}
